    if (left == -1) {
      return false;
    }

    int right = binarySearch(nums, target, false);

    return nums.length / 2 < right - left + 1;
  }

  static int binarySearch(int[] nums, int target, boolean leftmost) {
    int left = 0;
    int right = nums.length;

    while (left + 1 < right) {
      int mid = (right + left) / 2;

      if (nums[mid] == target) {
        if (leftmost) {
